import { Button } from '@refy-design/web';
import { Input } from '@refy-design/web';
import { StickyFooter } from '@refy-design/web';
import { useState } from 'react';
const stack = { display: 'grid', gap: 'var(--space-4)', minWidth: 0 } as const;
function StickyFooterExample() {
  const [saved, setSaved] = useState('Aurora project'),
    [value, setValue] = useState(saved),
    [status, setStatus] = useState('');
  return (
    <form
      style={stack}
      onSubmit={(e) => {
        e.preventDefault();
        setSaved(value);
        setStatus('Changes saved in this session.');
      }}
    >
      <Input
        label="Project name"
        value={value}
        onChange={(e) => setValue(e.target.value)}
      />
      <p>Saved value: {saved}</p>
      <StickyFooter start={value === saved ? 'No changes' : 'Unsaved changes'}>
        <Button
          type="button"
          onClick={() => {
            setValue(saved);
            setStatus('Editing cancelled.');
          }}
        >
          Cancel
        </Button>
        <Button type="submit" variant="primary">
          Save changes
        </Button>
      </StickyFooter>
      {status && <p role="status">{status}</p>}
    </form>
  );
}
export function Example() {
  return <StickyFooterExample />;
}
